import heapq

def top_k_frequent_words(words, k):
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1

    heap = [(-count, word) for word, count in counts.items()]
    heapq.heapify(heap)

    return [heapq.heappop(heap)[1] for _ in range(k)]

